// Authenticate incoming webhook using secret header or Bearer token
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || input;

const providedSecret = headers['x-mediator-secret'] 
  || (headers['authorization'] ? headers['authorization'].replace(/^Bearer\s+/i, '') : '')
  || body.webhook_secret;

// Matches backend default API_SECRET_KEY / N8N_WEBHOOK_SECRET
const expectedSecret = $env.N8N_WEBHOOK_SECRET || $env.API_SECRET_KEY || 'dev-mediator-key-123';

const isAuthorized = Boolean(providedSecret && providedSecret === expectedSecret);

return [{
  json: {
    isAuthorized,
    reason: isAuthorized ? null : 'Unauthorized: Invalid or missing X-Mediator-Secret authentication token',
    event_id: body.event_id || 'unknown',
    body
  }
}];

// Validate schema and event_type
const body = $json.body || $json;

const requiredFields = ['event_id', 'event_type', 'project_id', 'resolution_id', 'decision_text', 'decided_by', 'timestamp'];
const missing = requiredFields.filter(f => !body[f]);

const isValidType = body.event_type === 'decision.approved' || body.event_type === 'decision.modified';

if (missing.length > 0 || !isValidType) {
  return [{
    json: {
      isValid: false,
      reason: missing.length > 0 
        ? `Missing required fields: ${missing.join(', ')}` 
        : `Invalid event_type: ${body.event_type}. Must be decision.approved or decision.modified`,
      event_id: body.event_id || 'unknown'
    }
  }];
}

return [{
  json: {
    isValid: true,
    ...body
  }
}];

// Deduplication cache within workflow state using stable decision-based event ID
const eventId = $json.event_id;
const staticData = $getWorkflowStaticData('global');
staticData.processedEvents = staticData.processedEvents || {};

if (staticData.processedEvents[eventId]) {
  return [{
    json: {
      isDuplicate: true,
      event_id: eventId,
      message: 'Event already processed; no duplicate announcement sent'
    }
  }];
}

staticData.processedEvents[eventId] = new Date().toISOString();

return [{
  json: {
    isDuplicate: false,
    ...$json
  }
}];

// Format announcement for Slack & strictly sanitize test payload for Beeceptor
const item = $json;
const targetChannel = item.channel_id || item.channel_name || item.slack_channel || '#general';

const formattedSlackText = `🎉 *Team Alignment Commitment Confirmed!*\n\n` +
  `• *Project*: \`${item.project_id}\`\n` +
  `• *Channel*: ${targetChannel}\n` +
  `• *Decision*: "${item.decision_text}"\n` +
  `• *Decided By*: ${item.decided_by}\n` +
  `• *Resolution ID*: \`${item.resolution_id}\`\n` +
  `• *Timestamp*: ${item.timestamp}\n\n` +
  `_This decision was human-approved and is now binding on the project team._`;

// Sanitized audit payload for Beeceptor: masks PII/emails and redacts any potential secrets
const sanitizedDecidedBy = String(item.decided_by || '').replace(
  /([a-zA-Z0-9_\-\.]+)@([a-zA-Z0-9_\-\.]+)/g,
  (m, u, d) => `${u[0]}***@${d}`
);
const sanitizedSnippet = String(item.decision_text || '')
  .replace(/([a-zA-Z0-9_\-\.]+)@([a-zA-Z0-9_\-\.]+)/g, '[sanitized_email]')
  .replace(/(?:xox[baprs]|sk-|ghp_|Bearer\s+)[a-zA-Z0-9_\-]+/gi, '[redacted_secret]')
  .substring(0, 100);

const beeceptorPayload = {
  audit_source: "n8n_decision_automation",
  event_id: item.event_id,
  event_type: item.event_type,
  project_id: item.project_id,
  resolution_id: item.resolution_id,
  decision_snippet: sanitizedSnippet,
  decided_by: sanitizedDecidedBy,
  timestamp: item.timestamp,
  target_channel: targetChannel,
  data_classification: "sanitized_synthetic_audit"
};

return [{
  json: {
    ...item,
    targetChannel,
    formattedSlackText,
    beeceptorPayload
  }
}];
